	"dataSources": {
		"ds_3uDpdj17": {
			"name": "Sankey - FinOps - Domains - Capabilities",
			"options": {
				"query": "| inputlookup FinOpsDomainsCapabilities.csv \n| stats count by Domains, Capabilities \n| sort -Domains",
				"queryParameters": {
					"earliest": "0",
					"latest": ""
				}
			},
			"type": "ds.search"
		},
		"ds_5fSzWOqi": {
			"name": "Allocate multi-currency charges per application",
			"options": {
				"extend": "ds_xFobGfXE",
				"query": "| search ProviderName=$ProviderName$ \n| spath input=Tags output=Application path=application \n| spath input=Tags output=Environment path=environment \n| spath input=Tags output=BusinessUnit path=business_unit \n| stats sum(BilledCost) AS TotalBilledCost \n    BY Application, ProviderName, BillingAccountId, BillingAccountName, BillingCurrency"
			},
			"type": "ds.chain"
		},
		"ds_HOisVZBX": {
			"name": "Report refunds by subaccount within a billing period",
			"options": {
				"extend": "ds_xFobGfXE",
				"query": "| search ProviderName=$ProviderName$ ServiceCategory=$ServiceCategory$\n| stats sum(BilledCost) AS TotalBilledCost \n    BY ProviderName, BillingAccountId, SubAccountId, SubAccountName, ServiceCategory"
			},
			"type": "ds.chain"
		},
		"ds_J4evhrdt": {
			"name": "Provider Name",
			"options": {
				"extend": "ds_LxaqwirY",
				"query": "| dedup ProviderName \n| table ProviderName"
			},
			"type": "ds.chain"
		},
		"ds_LxaqwirY": {
			"name": "FOCUSBase - BillingPeriod",
			"options": {
				"query": "index=\"main\" sourcetype=\"csv\" \n| eval BillingPeriodStart = strptime(BillingPeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval ChargePeriodStart = strptime(ChargePeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval BillingPeriodEnd = strptime(BillingPeriodEnd, \"%Y-%m-%d %H:%M:%S\") \n| eval ChargePeriodEnd = strptime(ChargePeriodEnd, \"%Y-%m-%d %H:%M:%S\") \n| eval Global_Start = strptime(\"$global_time.earliest$\", \"%Y-%m-%dT%H:%M:%S.%QZ\") \n| eval Global_End = strptime(\"$global_time.latest$\", \"%Y-%m-%dT%H:%M:%S.%QZ\") \n| where BillingPeriodStart >= Global_Start AND BillingPeriodEnd <= Global_End\n| table *"
			},
			"type": "ds.search"
		},
		"ds_VY2da9PN": {
			"name": "Service Category",
			"options": {
				"extend": "ds_xFobGfXE",
				"query": "| search ProviderName=\"$ProviderName$\" \n| eval ServiceCategory = if(ServiceCategory==\"\", \"No ServiceCategory\", ServiceCategory) \n| dedup ServiceCategory \n| table ServiceCategory"
			},
			"type": "ds.chain"
		},
		"ds_YAvFnFcJ": {
			"name": "Analyze the different metered costs for a particular SKU",
			"options": {
				"extend": "ds_xFobGfXE",
				"query": "| search ProviderName=$ProviderName$ \n| eval ChargePeriodStart = strftime(BillingPeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval ChargePeriodEnd = strftime(BillingPeriodEnd, \"%Y-%m-%d %H:%M:%S\") \n| stats sum(PricingQuantity) AS TotalPricingQuantity,\n    sum(ListCost) AS TotalListCost,\n    sum(EffectiveCost) AS TotalEffectiveCost \n    BY ProviderName, ChargePeriodStart, ChargePeriodEnd, SkuId, SkuPriceId, PricingUnit, ListUnitPrice \n| sort ChargePeriodStart \n| head 100"
			},
			"type": "ds.chain"
		},
		"ds_aUkjWsOF": {
			"name": "Analyze tag coverage",
			"options": {
				"extend": "ds_LxaqwirY",
				"query": "| search ProviderName=$ProviderName$ EffectiveCost > 0 \n| eval TaggedCost = if(like(Tags, \"%\\\"application\\\"%\"), EffectiveCost, 0) \n| eventstats sum(EffectiveCost) AS TotalEffectiveCost, sum(TaggedCost) AS TotalTaggedCost \n| eval TaggedPercentage = round((TotalTaggedCost / TotalEffectiveCost) * 100, 2) \n| dedup TaggedPercentage \n| table TaggedPercentage"
			},
			"type": "ds.chain"
		},
		"ds_gCHZnOfm": {
			"name": "Allocate - Total mutal-currency charges",
			"options": {
				"extend": "ds_xFobGfXE",
				"query": "| spath input=Tags output=Application path=application \n| spath input=Tags output=Environment path=environment \n| spath input=Tags output=BusinessUnit path=business_unit \n| search ProviderName=$ProviderName$ Application!=\"\"\n| stats sum(BilledCost) AS TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_lS0IkD6t": {
			"name": "Allocation - Total Refunds",
			"options": {
				"extend": "ds_xFobGfXE",
				"query": "| search ProviderName=$ProviderName$ ServiceCategory=$ServiceCategory$\n| stats sum(BilledCost) AS TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_n6LtddhB": {
			"name": "Report costs by service category and subcategory",
			"options": {
				"extend": "ds_LxaqwirY",
				"query": "| search ProviderName=$ProviderName$ ServiceCategory=$ServiceCategory$ \n| eval BillingPeriodStart = strftime(BillingPeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval BillingPeriodEnd = strftime(BillingPeriodEnd, \"%Y-%m-%d %H:%M:%S\") \n| stats sum(BilledCost) AS TotalBilledCost \n    BY ProviderName, BillingCurrency, BillingPeriodStart, ServiceCategory \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_u1Vppw13": {
			"name": "FinOps - Capabilities - Use Cases - Personas",
			"options": {
				"query": "| inputlookup FinOpsCapabilitiesUseCasePersonas.csv\n| stats count by \"Capabilities\", \"Personas\""
			},
			"type": "ds.search"
		},
		"ds_xFobGfXE": {
			"name": "FOCUSBase - ChargePeriod",
			"options": {
				"query": "index=\"main\" sourcetype=\"csv\" \n| eval BillingPeriodStart = strptime(BillingPeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval ChargePeriodStart = strptime(ChargePeriodStart, \"%Y-%m-%d %H:%M:%S\") \n| eval BillingPeriodEnd = strptime(BillingPeriodEnd, \"%Y-%m-%d %H:%M:%S\") \n| eval ChargePeriodEnd = strptime(ChargePeriodEnd, \"%Y-%m-%d %H:%M:%S\") \n| eval Global_Start = strptime(\"$global_time.earliest$\", \"%Y-%m-%dT%H:%M:%S.%QZ\") \n| eval Global_End = strptime(\"$global_time.latest$\", \"%Y-%m-%dT%H:%M:%S.%QZ\") \n| where ChargePeriodStart >= Global_Start AND ChargePeriodEnd <= Global_End \n| table *"
			},
			"type": "ds.search"
		},
		"ds_yrY5Lx8F": {
			"name": "Identify which provider versions your datasets have been generated with",
			"options": {
				"extend": "ds_xFobGfXE",
				"query": "| search ProviderName=$ProviderName$ \n| dedup ProviderName, PublisherName \n| table ProviderName, PublisherName"
			},
			"type": "ds.chain"
		},
		"ds_BJR28mvX": {
			"type": "ds.search",
			"options": {
				"query": "| inputlookup Test.csv \n| stats count by Domains, Capabilities \n| sort Domains",
				"queryParameters": {
					"earliest": "0",
					"latest": ""
				}
			},
			"name": "Test"
		}
	},
